cat >> src/orchestration/orchestratorHelpers.test.ts <<'EOF'

describe('sumUsage', () => {
  it('adds each token field across only the rounds that reported usage', () => {
    expect(sumUsage([USAGE(11, 2, 13), undefined, USAGE(23, 3, 26)])).toEqual(USAGE(34, 5, 39));
  });

  it('reports nothing when no round reported usage', () => {
    expect(sumUsage([undefined, undefined])).toBeUndefined();
  });

  it('passes a lone reported round through unchanged', () => {
    expect(sumUsage([undefined, USAGE(10, 5, 15)])).toEqual(USAGE(10, 5, 15));
  });
});
EOF
